package gen

import (
	"encoding/json"
	"path/filepath"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"

	"github.com/txn2/mcp-data-platform/bench/internal/protocol"
)

const protocolHeader = "# Generated by bench/seedgen; recall/update answers are computed from the seeded dataset.\n" +
	"# Do not edit; regenerate with `make bench-gen`.\n"

// TestCommittedProtocolsMatch is the reproducibility gate for the S5 protocols:
// the committed YAML and the lifecycle smoke must equal a fresh regeneration.
func TestCommittedProtocolsMatch(t *testing.T) {
	ds := Generate()
	root := "../.."
	protocols := ds.Protocols()

	committed, err := protocol.Load(filepath.Join(root, "protocols"))
	if err != nil {
		t.Fatalf("load committed protocols: %v (run `make bench-gen`)", err)
	}
	if got, want := protocol.Hash(committed), protocol.Hash(protocols); got != want {
		t.Errorf("committed protocol hash %s != regenerated %s; run `make bench-gen`", got, want)
	}
	for _, p := range protocols {
		raw, err := yaml.Marshal(p)
		if err != nil {
			t.Fatalf("marshal %s: %v", p.ID, err)
		}
		compareFile(t, filepath.Join(root, "protocols", p.ID+".yaml"), append([]byte(protocolHeader), raw...))
	}
	smoke, err := json.MarshalIndent(ScriptedLifecycleSmoke(protocols), "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	compareFile(t, filepath.Join(root, "protocols", "scripted-lifecycle-smoke.json"), append(smoke, '\n'))
}

func TestProtocolSetSize(t *testing.T) {
	if got := len(Generate().Protocols()); got != 30 {
		t.Fatalf("protocol set size = %d, want 30", got)
	}
}

// TestProtocolUpdatesFlip guarantees every supersede stage changes the answer;
// a stage whose corrected recall equals the taught recall would measure nothing.
func TestProtocolUpdatesFlip(t *testing.T) {
	updates := 0
	for _, p := range Generate().Protocols() {
		if p.Update == nil {
			continue
		}
		updates++
		before := answerString(p.Recall.Grading)
		after := answerString(p.Update.Recall.Grading)
		if before == after {
			t.Errorf("%s: update does not flip the answer (%q)", p.ID, before)
		}
	}
	if updates != 10 {
		t.Fatalf("expected 10 supersede protocols, got %d", updates)
	}
}

// TestProtocolsTeachNovelFacts guards the clean-measurement invariant: an S5
// fact must not reuse a seeded knowledge-page slug, or a learner could answer
// from the seed instead of the promoted knowledge.
func TestProtocolsTeachNovelFacts(t *testing.T) {
	seeded := map[string]bool{
		"revenue-reporting-policy": true, "bench-warehouse-guide": true,
		"fiscal-calendar-policy": true, "customer-tier-definitions": true,
	}
	for _, p := range Generate().Protocols() {
		if p.Page != nil && seeded[p.Page.Slug] {
			t.Errorf("%s reuses seeded page slug %q", p.ID, p.Page.Slug)
		}
	}
}

// TestScriptedLifecycleSmokeCoversStages checks the smoke plays every stage each
// protocol declares.
func TestScriptedLifecycleSmokeCoversStages(t *testing.T) {
	protocols := Generate().Protocols()
	smoke := ScriptedLifecycleSmoke(protocols)
	for _, p := range protocols {
		stages, ok := smoke[p.ID]
		if !ok {
			t.Fatalf("smoke missing protocol %s", p.ID)
		}
		for _, required := range []string{"teach", "recall", "abstain"} {
			if len(stages[required]) == 0 {
				t.Errorf("%s: smoke missing %s stage", p.ID, required)
			}
		}
		if p.Transfer != nil && len(stages["transfer"]) == 0 {
			t.Errorf("%s: smoke missing transfer stage", p.ID)
		}
		if p.Update != nil && (len(stages["update"]) == 0 || len(stages["update_recall"]) == 0) {
			t.Errorf("%s: smoke missing update stages", p.ID)
		}
		// The recall smoke must end on a computed final answer.
		recall := stages["recall"]
		if last := recall[len(recall)-1].FinalText; !strings.Contains(last, "FINAL ANSWER:") {
			t.Errorf("%s: recall smoke step is not a final answer: %q", p.ID, last)
		}
	}
}
